private void cboWhite_DrawItem(object sender, DrawItemEventArgs e)
{
    ComboBox combo = sender as ComboBox;
    if (combo == null)
        return;
    e.Graphics.FillRectangle(Brushes.White, e.Bounds);
    string text = e.Index >= 0 && e.Index < combo.Items.Count
        ? Convert.ToString(combo.Items[e.Index])
        : combo.Text;
    TextRenderer.DrawText(e.Graphics, text, combo.Font, e.Bounds, Color.FromArgb(32, 31, 53), TextFormatFlags.Left | TextFormatFlags.VerticalCenter | TextFormatFlags.EndEllipsis);
    if ((e.State & DrawItemState.Focus) == DrawItemState.Focus)
        e.DrawFocusRectangle();
}

