private void frmDeviceDepPeriodList_Load(object sender, EventArgs e)
{
    if (!UserSession.HasPermission(PERMISSION_VIEW))
    {
        MessageManager.Warning("Bạn không có quyền xem kỳ khấu hao.");
        Close();
        return;
    }
    var monthList = new List<MonthItem>();
    monthList.Add(new MonthItem { Value = 0, DisplayText = "--Tất cả tháng--" });
    for (int month = 1; month <= 12; month++)
        monthList.Add(new MonthItem { Value = month, DisplayText = "Tháng " + month });
    cboMonth.Properties.DataSource = monthList;
    cboMonth.Properties.DisplayMember = "DisplayText";
    cboMonth.Properties.ValueMember = "Value";
    cboMonth.EditValue = 0;
    var statusList = new List<StatusItem>();
    statusList.Add(new StatusItem { Value = 0, DisplayText = "--Tất cả trạng thái--" });
    statusList.Add(new StatusItem { Value = 2, DisplayText = "Đã ghi nhận" });
    statusList.Add(new StatusItem { Value = 3, DisplayText = "Đã hoàn nhập" });
    cboStatus.Properties.DataSource = statusList;
    cboStatus.Properties.DisplayMember = "DisplayText";
    cboStatus.Properties.ValueMember = "Value";
    cboStatus.EditValue = 0;
    txtYearID.EditValue = DateTime.Today.Year;
    uOffice.InitData();
    btnReverse.Enabled = false;
    new Thread(LoadData).Start();
}

