public void LoadData()
{
    if (InvokeRequired)
        Invoke(new MethodInvoker(LoadData));
    else
    {
        int? yearID = txtYearKK.EditValueInt32.HasValue && txtYearKK.EditValueInt32.Value > 0
            ? txtYearKK.EditValueInt32
            : (int?)null;
        int? statusID = cboStatus.EditValue == null ? (int?)null : (int?)cboStatus.EditValue;
        FAM_DeviceChecking obj = new FAM_DeviceChecking();
        dtbData = obj.Search(
            uOffice.EditValueInt32,
            lookupPlaceID.EditValueInt32,
            yearID,
            null,
            null,
            statusID,
            txtKeyWork.TextTrim);
        if (dtbData == null)
        {
            ErrorManager.Error("Việc tải danh sách đợt bị lỗi! " + (obj.ErrorException == null ? "" : obj.ErrorException.Message));
            return;
        }
        gcData.DataSource = dtbData;
        SYS_GridColumnService.InitGridColumn(gvData, "FAM_DeviceChecking_Search", bolIsRefresh);
        bolIsRefresh = false;
        UpdateToolbarState();
    }
}

