        private void btnClose_Click(object sender, EventArgs e)
        {
            Close();
        }

        private void btnExport_Click(object sender, EventArgs e)
        {
            try
            {
                if (dtbDetails == null || dtbDetails.Rows.Count == 0)
                {
                    XtraMessageBox.Show("Không có dữ liệu để xuất!", "Thông báo", MessageBoxButtons.OK, MessageBoxIcon.Information);
                    return;
                }

                using (SaveFileDialog saveDialog = new SaveFileDialog())
                {
                    saveDialog.Filter = "Excel File|*.xlsx";
                    saveDialog.Title = "Xuất danh sách tài sản theo kỳ";
                    saveDialog.FileName = $"DanhSachTaiSan_{txtYearID.Value}_{cboMonth.Text}_{DateTime.Now:yyyyMMddHHmmss}.xlsx";

                    if (saveDialog.ShowDialog() == DialogResult.OK)
                    {
                        gcDetails.ExportToXlsx(saveDialog.FileName);
                        XtraMessageBox.Show("Xuất dữ liệu thành công!", "Thông báo", MessageBoxButtons.OK, MessageBoxIcon.Information);
                    }
                }
            }
            catch (Exception ex)
            {
                ErrorManager.Error(ex);
            }
        }
    }
}

